import * as T from './vendor/three.module.min.js';
import {createTikiActor79} from './tiki-garden-cast-v85.js';
import {GARDEN_DECOR85} from './tiki-garden-dressing-v85.js';
import {nextPaint} from './bath-loading-v72.js';
const cache=new Map();let meta;
export async function preloadGardenPeople85(report=()=>{}){const root=new URL('./textures/tiki-garden-v85/npc/',import.meta.url);meta=await(await fetch(new URL('manifest.json',root))).json();const loader=new T.TextureLoader();let n=0;for(const role of ['footbath','botanist']){for(const name of ['face','face-closed','body','hair']){const t=await loader.loadAsync(new URL(role+'/'+name+'.png',root).href);t.colorSpace=T.SRGBColorSpace;t.minFilter=t.magFilter=T.NearestFilter;t.generateMipmaps=false;cache.set(role+'/'+name,t);report(++n/8);}await nextPaint();}}
function shoes(root,body){const m=new T.MeshLambertMaterial({map:body,flatShading:true}),dark=new T.MeshLambertMaterial({color:0x252622,flatShading:true});for(let i=0;i<2;i++){const g=new T.Group();root.add(g);g.position.set(-5.55+i*.24,.022,1.30);g.rotation.y=.31-i*.20;const shape=new T.Shape();shape.moveTo(-.057,-.11);shape.lineTo(.057,-.11);shape.quadraticCurveTo(.08,.07,.045,.16);shape.quadraticCurveTo(0,.185,-.047,.159);shape.quadraticCurveTo(-.08,.06,-.057,-.11);const geo=new T.ExtrudeGeometry(shape,{depth:.070,bevelEnabled:true,bevelThickness:.014,bevelSize:.013,bevelSegments:1,steps:1,curveSegments:5});geo.rotateX(-Math.PI/2);const p=geo.attributes.position,u=geo.attributes.uv;for(let j=0;j<u.count;j++)u.setXY(j,.53+(p.getX(j)+.085)/.17*.42,.02+(p.getZ(j)+.18)/.3*.20);const o=new T.Mesh(geo,m);g.add(o);const hole=new T.Mesh(new T.CircleGeometry(.038,10),dark);hole.rotation.x=-Math.PI/2;hole.scale.y=1.4;hole.position.set(0,.088,-.055);g.add(hole);for(let j=0;j<4;j++){const lace=new T.Mesh(new T.BoxGeometry(.076,.004,.008),new T.MeshLambertMaterial({color:0xada18a}));lace.position.set(0,.095,.015+j*.022);g.add(lace);}}}
export async function createGardenPeople85(scene){const root=new T.Group();root.name='Two individually UV textured garden visitors';scene.add(root);const actors=[];for(const role of ['footbath','botanist']){const a=meta.characters[role].face_landmarks,p=GARDEN_DECOR85[role],textures={face:cache.get(role+'/face'),faceBlink:cache.get(role+'/face-closed'),body:cache.get(role+'/body'),hair:cache.get(role+'/hair')};const landmarks=[(a.image_left_eye.image_uv[1]+a.image_right_eye.image_uv[1])/2,a.nose_base.image_uv[1],a.mouth_center.image_uv[1],a.lower_chin.image_uv[1],a.image_left_eye.image_uv[0],a.image_right_eye.image_uv[0]];const actor=createTikiActor79(T,role,textures,{landmarks,seatHeight:.24,skinUV:[.265,.40],phase:role==='footbath'?1.25:0});actor.group.position.set(p.x,0,p.z);actor.group.rotation.y=p.ry;root.add(actor.group);actors.push(actor);await nextPaint();}shoes(root,cache.get('footbath/body'));return{root,actors,textures:[...cache.values()],update(t){actors.forEach(a=>a.update(t));},react(t){actors[1].react(t);},dispose(){actors.forEach(a=>a.dispose());root.removeFromParent();}};}
